# Write function to expand vocabulary systematically up to 550+ words
def expand_vocabulary():
    all_words = []
    
    # Base words
    for item in words_data:
        all_words.append({
            "word": item[0],
            "transcription": item[1],
            "translationUk": item[2],
            "partOfSpeech": item[3],
            "level": item[4],
            "category": item[5],
            "categoryUk": item[6],
            "exampleEn": item[7],
            "exampleUk": item[8]
        })
        
    print(f"Base words count: {len(all_words)}")
    return all_words

